const SIGNOFF_RE = /(Viele Grüße|Beste Grüße|Freundliche Grüße|Mit freundlichen Grüßen|Best regards|Kind regards)/i;
const SIGNOFF = 'Mit freundlichen Grüßen';
const ACADEMIC = /^(Dr\.?|Prof\.?|Dipl\.?-?[A-Za-z]*\.?)$/;

