  const parts = sentences.map((x) => x.trim());
  const last = /\?$/.test(parts[parts.length - 1]) ? parts.pop() : null;
  const first = parts.shift();
  return [first, parts.join(' '), last].filter((x) => x && x.trim()).join('\n\n');
